feed:
  {{ title }}
{% if config.description %}
  {{ config.description }}
{% endif %}


  {{ feed_url }}
{% if last_updated %}
  {{ last_updated | rfc3339 }}
{% endif %}
{% if config.author %}

    {{ config.author }}

{% endif %}
{% for page in pages %}

    {{ page.title }}

    {{ page.permalink }}
    {{ page.date | rfc3339 }}
    {{ page.last_changed() | rfc3339 }}
{% if page.summary %}
    {{ page.summary }}
{% endif %}
    {{ page.content }}

{% endfor %}
